SELECT DATE_TRUNC('WEEK', signup_date) AS week_start, city, CASE WHEN age >= 65 THEN 'HIGH' ELSE 'LOW' END AS age_tier, CORR(credit_limit, age) AS corr_credit_limit_age, SIZE(COLLECT_SET(segment)) AS num_segments, APPROX_PERCENTILE(credit_limit, 0.9) AS credit_limit_p90, GROUPING_ID() AS grouping_id FROM customers GROUP BY ROLLUP (DATE_TRUNC('WEEK', signup_date), city, CASE WHEN age >= 65 THEN 'HIGH' ELSE 'LOW' END) HAVING num_segments < 1 ORDER BY age_tier;
